//! PlotterDemo — generated by mobius_codegen.
//!
//! Wiring follows the egui_mobius book: Path A state lives in the
//! `state::*` cells, citizens' Path B events drain through actions
//! once per frame, and the registry handles lifecycle only.

mod citizens;
mod state;

use eframe::egui;
use egui_citizen::Registry;
use egui_dock::{DockArea, DockState, NodeIndex};

/// One dock tab per docked citizen instance.
#[derive(Clone, Copy, PartialEq)]
pub enum Tab {
    Controls,
    Scope,
}

impl Tab {
    /// The instance id — registry name and citizen id.
    fn id(self) -> &'static str {
        match self {
            Tab::Controls => "controls",
            Tab::Scope => "scope",
        }
    }
}

struct App {
    registry: Registry,
    dock_state: DockState<Tab>,
    bench: state::Bench,
    controls: citizens::Controls,
    scope: citizens::Scope,
}

impl App {
    fn new() -> Self {
        let mut registry = Registry::new();
        let controls_state = registry.add().with_name("controls");
        let scope_state = registry.add().with_name("scope");
        registry.activate("controls");
        let _ = registry.drain_messages(); // discard setup messages

        // Dock layout from the @layout dock() directives.
        let mut dock_state = DockState::new(vec![Tab::Scope]);
        let _ = dock_state.main_surface_mut().split_left(NodeIndex::root(), 0.30, vec![Tab::Controls]);
        Self {
            registry,
            dock_state,
            bench: state::Bench::new(),
            controls: citizens::Controls::with_id(controls_state, "controls"),
            scope: citizens::Scope::with_id(scope_state, "scope"),
        }
    }
}

struct TabViewer<'a> {
    registry: &'a mut Registry,
    bench: &'a state::Bench,
    controls: &'a mut citizens::Controls,
    scope: &'a mut citizens::Scope,
}

impl egui_dock::TabViewer for TabViewer<'_> {
    type Tab = Tab;

    fn id(&mut self, tab: &mut Tab) -> egui::Id {
        egui::Id::new(tab.id())
    }

    fn title(&mut self, tab: &mut Tab) -> egui::WidgetText {
        tab.id().into()
    }

    fn ui(&mut self, ui: &mut egui::Ui, tab: &mut Tab) {
        match tab {
            Tab::Controls => self.controls.show(ui, self.bench),
            Tab::Scope => self.scope.show(ui, self.bench),
        }
    }

    fn on_tab_button(&mut self, tab: &mut Tab, response: &egui::Response) {
        if response.clicked() {
            self.registry.activate(tab.id());
        }
    }
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {

        let mut viewer = TabViewer {
            registry: &mut self.registry,
            bench: &self.bench,
            controls: &mut self.controls,
            scope: &mut self.scope,
        };
        DockArea::new(&mut self.dock_state).show_inside(ui, &mut viewer);
        // Registry lifecycle messages — drained after the panels show.
        for _msg in self.registry.drain_messages() {}
    }
}

fn main() -> Result<(), eframe::Error> {
    eframe::run_native(
        "PlotterDemo",
        eframe::NativeOptions {
            renderer: eframe::Renderer::Glow,
            viewport: egui::ViewportBuilder::default().with_inner_size([900.0, 420.0]),
            ..Default::default()
        },
        Box::new(|_cc| Ok(Box::new(App::new()))),
    )
}

#[cfg(test)]
mod headless {
    //! Headless harness — `egui_kittest` drives the app with no window
    //! and no GPU: frames step on a virtual clock, and widgets are
    //! reached through the accessibility tree. `cargo test` runs
    //! anywhere; `cargo test -- --ignored --nocapture` prints the tree.
    use super::App;
    use egui_kittest::Harness;
    use egui_kittest::kittest::Queryable;

    /// The app under harness, built as `main`'s creator builds it.
    fn harness() -> Harness<'static, App> {
        Harness::new_eframe(|_cc| App::new())
    }

    #[test]
    fn boots_and_runs_frames() {
        let mut harness = harness();
        for _ in 0..10 {
            harness.step();
        }
    }

    #[test]
    fn controls_reach_the_accessibility_tree() {
        let mut harness = harness();
        harness.step();
        assert!(
            harness.query_all_by_label("Enabled").next().is_some(),
            "Enabled is missing from the accessibility tree"
        );
    }

    #[test]
    #[ignore = "prints the widget tree: cargo test -- --ignored --nocapture"]
    fn dump_widget_tree() {
        let mut harness = harness();
        harness.step();
        println!("{:#?}", harness.root());
    }
}
